typedef enum pdf_objkind_e
{
        PDF_INT = 'i',
        PDF_REAL = 'f',
        PDF_STRING = 's',
        PDF_NAME = 'n',
        PDF_ARRAY = 'a',
        PDF_DICT = 'd',
        PDF_INDIRECT = 'r'
} pdf_objkind;

struct keyval
{
        pdf_obj *k;
        pdf_obj *v;
};

enum
{
        PDF_FLAGS_MARKED = 1,
        PDF_FLAGS_SORTED = 2,
        PDF_FLAGS_DIRTY = 4,
        PDF_FLAGS_MEMO_BASE = 8,
        PDF_FLAGS_MEMO_BASE_BOOL = 16
};

struct pdf_obj
{
        short refs;
        unsigned char kind;
        unsigned char flags;
};

typedef struct
{
        pdf_obj super;
        union
        {
                int64_t i;
                float f;
        } u;
} pdf_obj_num;

typedef struct
{
        pdf_obj super;
        char *text; /* utf8 encoded text string */
        size_t len;
        char buf[1];
} pdf_obj_string;

typedef struct
{
        pdf_obj super;
        char n[1];
} pdf_obj_name;

typedef struct
{
        pdf_obj super;
        pdf_document *doc;
        int parent_num;
        int len;
        int cap;
        pdf_obj **items;
} pdf_obj_array;

typedef struct
{
        pdf_obj super;
        pdf_document *doc;
        int parent_num;
        int len;
        int cap;
        struct keyval *items;
} pdf_obj_dict;

typedef struct
{
        pdf_obj super;
        pdf_document *doc; /* Only needed for arrays, dicts and indirects */
        int num;
        int gen;
} pdf_obj_ref;
